type ListClientsForExportRow struct {
	ID                 int64     `json:"id"`
	Name               string    `json:"name"`
	Phone              string    `json:"phone"`
	ClientType         string    `json:"client_type"`
	IsActive           bool      `json:"is_active"`
	CreatedAt          time.Time `json:"created_at"`
	ValidLoyaltyPoints int64     `json:"valid_loyalty_points"`
	BranchID           int64     `json:"branch_id"`
	TotalSpent         int64     `json:"total_spent"`
	InvoiceCount       int64     `json:"invoice_count"`
	LastVisit          time.Time `json:"last_visit"`
}

// Feeds the clients CSV export: one row per (client, branch) for every
// client who bought something, so the caller can write a file per branch.
// A client "belongs" to a branch because a non-cancelled invoice there is
// theirs. The invoice's client is resolved by either identity a till has
// used: the shared client_uid (current), or the older (register,
// branch_client_id) client_links entry -- an invoice carrying only one of
// them still counts. branch_ids (empty = every branch) and the
// [date_from, date_to) window (either bound optional) narrow which
// invoices count; spend/invoice figures are for that same scope, not
// lifetime. Central admin invoices have no branch (branch_id 0) and are only
// included when no branch is selected, the same rule as
// ListClientsBySpending. With no branch and no date set, clients who never
// bought anything are listed too (branch_id 0, zero spend). A client is
// listed under every branch they bought from, not only their home branch
// (clients.branch_id, the first one); the home branch adds a zero-spend row
// when they have no purchases there. Cancelled and
// hidden-from-reports branch invoices are skipped as everywhere else, unless
// include_excluded is set.
// Home branch (clients.branch_id): a client is also listed under it when
// they haven't bought there in this scope, e.g. one imported with a branch
// and no sales yet. Only for an explicit branch pick and no dates, since
// zero spend can't match a date window; the same hidden-branch rule as
// purchases applies.
func (q *Queries) ListClientsForExport(ctx context.Context, arg ListClientsForExportParams) ([]ListClientsForExportRow, error) {
	rows, err := q.db.QueryContext(ctx, listClientsForExport,
		pq.Array(arg.BranchIds),
		arg.DateFrom,
		arg.DateTo,
		arg.IncludeExcluded,
		arg.ClientType,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListClientsForExportRow{}
	for rows.Next() {
		var i ListClientsForExportRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Phone,
			&i.ClientType,
			&i.IsActive,
			&i.CreatedAt,
			&i.ValidLoyaltyPoints,
			&i.BranchID,
			&i.TotalSpent,
			&i.InvoiceCount,
			&i.LastVisit,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listClientsUpdatedSince = `-- name: ListClientsUpdatedSince :many
SELECT id, name, phone, total_loyalty_points, valid_loyalty_points, created_at, updated_at, client_type, uid, is_active, branch_id FROM clients
WHERE updated_at > $1 AND client_type = 'retail'
ORDER BY updated_at
`

// Feeds the branch catch-up endpoint (see branch_catchup.go), same pattern
// as currencies/cashbox_accounts/products. Wholesale clients never appear
// here -- they're a central-office concept, not something a branch till
// should ever see in its client search. Converting an already-synced
// retail client to wholesale won't retract it from branches that already
// have it locally (no delete propagation exists for any synced entity
// today); acceptable since that conversion is expected to be rare.
func (q *Queries) ListClientsUpdatedSince(ctx context.Context, updatedAt time.Time) ([]Client, error) {
	rows, err := q.db.QueryContext(ctx, listClientsUpdatedSince, updatedAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Client{}
	for rows.Next() {
		var i Client
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Phone,
			&i.TotalLoyaltyPoints,
			&i.ValidLoyaltyPoints,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ClientType,
			&i.Uid,
			&i.IsActive,
			&i.BranchID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listClientsUpdatedSincePaged = `-- name: ListClientsUpdatedSincePaged :many
SELECT id, name, phone, total_loyalty_points, valid_loyalty_points, created_at, updated_at, client_type, uid, is_active, branch_id FROM clients
WHERE client_type = 'retail'
  AND (updated_at, id) > ($1::timestamptz, $2::bigint)
ORDER BY updated_at, id
LIMIT $3
`

type ListClientsUpdatedSincePagedParams struct {
	AfterUpdatedAt time.Time `json:"after_updated_at"`
	AfterID        int64     `json:"after_id"`
	RowLimit       int32     `json:"row_limit"`
}

// Keyset-paginated form of ListClientsUpdatedSince for a branch doing a
// full catch-up (cursor reset): ordered by (updated_at, id) so a page
// boundary that falls between two rows sharing an updated_at can't drop or
// repeat one. after_updated_at/after_id are the last row of the previous
// page (zero-time / 0 for the first page).
func (q *Queries) ListClientsUpdatedSincePaged(ctx context.Context, arg ListClientsUpdatedSincePagedParams) ([]Client, error) {
	rows, err := q.db.QueryContext(ctx, listClientsUpdatedSincePaged, arg.AfterUpdatedAt, arg.AfterID, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Client{}
	for rows.Next() {
		var i Client
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Phone,
			&i.TotalLoyaltyPoints,
			&i.ValidLoyaltyPoints,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ClientType,
			&i.Uid,
			&i.IsActive,
			&i.BranchID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listClientsWithLoyalty = `-- name: ListClientsWithLoyalty :many
SELECT c.id, c.name, c.phone, c.total_loyalty_points, c.valid_loyalty_points, c.created_at, c.updated_at, c.client_type, c.uid, c.is_active, c.branch_id, COALESCE(bl.branch_points, 0)::bigint AS branch_loyalty_points
FROM clients c
LEFT JOIN (
  SELECT cl.client_id, SUM(bi.loyalty_points_delta) AS branch_points
  FROM branch_invoices bi
  JOIN client_links cl ON cl.register_id = bi.register_id AND cl.branch_client_id = bi.branch_client_id
  GROUP BY cl.client_id
) bl ON bl.client_id = c.id
WHERE $3::text IS NULL OR c.client_type = $3
ORDER BY c.name
LIMIT $1
OFFSET $2
`

type ListClientsWithLoyaltyParams struct {
	Limit      int32          `json:"limit"`
	Offset     int32          `json:"offset"`
	ClientType sql.NullString `json:"client_type"`
}

type ListClientsWithLoyaltyRow struct {
	ID                  int64         `json:"id"`
	Name                string        `json:"name"`
	Phone               string        `json:"phone"`
	TotalLoyaltyPoints  int64         `json:"total_loyalty_points"`
	ValidLoyaltyPoints  int64         `json:"valid_loyalty_points"`
	CreatedAt           time.Time     `json:"created_at"`
	UpdatedAt           time.Time     `json:"updated_at"`
	ClientType          string        `json:"client_type"`
	Uid                 uuid.UUID     `json:"uid"`
	IsActive            bool          `json:"is_active"`
	BranchID            sql.NullInt64 `json:"branch_id"`
	BranchLoyaltyPoints int64         `json:"branch_loyalty_points"`
}

// Same rows as ListClients, but with each branch's reported loyalty points
// (branch_invoices.loyalty_points_delta, via client_links) summed in
// alongside kashi's own admin-invoice points. Used by the admin clients
// page so the displayed balance isn't missing everything earned at a
// branch till.
func (q *Queries) ListClientsWithLoyalty(ctx context.Context, arg ListClientsWithLoyaltyParams) ([]ListClientsWithLoyaltyRow, error) {
	rows, err := q.db.QueryContext(ctx, listClientsWithLoyalty, arg.Limit, arg.Offset, arg.ClientType)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListClientsWithLoyaltyRow{}
	for rows.Next() {
		var i ListClientsWithLoyaltyRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Phone,
			&i.TotalLoyaltyPoints,
			&i.ValidLoyaltyPoints,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ClientType,
			&i.Uid,
			&i.IsActive,
			&i.BranchID,
			&i.BranchLoyaltyPoints,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const setClientBranchIfNull = `-- name: SetClientBranchIfNull :exec
UPDATE clients SET branch_id = $1
WHERE branch_id IS NULL
  AND id = COALESCE(
    (SELECT cu.id FROM clients cu WHERE cu.uid = $2),
    (SELECT cl.client_id FROM client_links cl
      WHERE cl.register_id = $3 AND cl.branch_client_id = $4)
  )
`

type SetClientBranchIfNullParams struct {
	BranchID       sql.NullInt64 `json:"branch_id"`
	ClientUid      uuid.NullUUID `json:"client_uid"`
	RegisterID     int64         `json:"register_id"`
	BranchClientID sql.NullInt64 `json:"branch_client_id"`
}

// A client's home branch is the first branch they bought from, so a branch
// invoice only sets it when none is set yet. The client is resolved by
// either identity a till has used (client_uid, else the register's local
// client id), as in ListClientsForExport. updated_at is left alone: the
// column isn't synced to tills, so this mustn't make them re-pull the client.
func (q *Queries) SetClientBranchIfNull(ctx context.Context, arg SetClientBranchIfNullParams) error {
	_, err := q.db.ExecContext(ctx, setClientBranchIfNull,
		arg.BranchID,
		arg.ClientUid,
		arg.RegisterID,
		arg.BranchClientID,
	)
	return err
}

const sumClientLoyaltyPoints = `-- name: SumClientLoyaltyPoints :one
SELECT COALESCE(SUM(bi.loyalty_points_delta), 0)::bigint AS total
FROM branch_invoices bi
JOIN client_links cl ON cl.register_id = bi.register_id AND cl.branch_client_id = bi.branch_client_id
WHERE cl.client_id = $1
`

// The redemption-time query: every branch's contribution to this client's
// loyalty balance, added up. Each branch is decisive for what it reports
// (loyalty_points_delta on branch_invoices) -- this never recomputes that
// number, only sums what's already been reported.
func (q *Queries) SumClientLoyaltyPoints(ctx context.Context, clientID int64) (int64, error) {
	row := q.db.QueryRowContext(ctx, sumClientLoyaltyPoints, clientID)
	var total int64
	err := row.Scan(&total)
	return total, err
}

const updateClient = `-- name: UpdateClient :one
UPDATE clients
  SET name = $2,
  phone = $3,
  client_type = $4,
  updated_at = now()
WHERE id = $1
RETURNING id, name, phone, total_loyalty_points, valid_loyalty_points, created_at, updated_at, client_type, uid, is_active, branch_id
`

type UpdateClientParams struct {
	ID         int64  `json:"id"`
	Name       string `json:"name"`
	Phone      string `json:"phone"`
	ClientType string `json:"client_type"`
}

func (q *Queries) UpdateClient(ctx context.Context, arg UpdateClientParams) (Client, error) {
	row := q.db.QueryRowContext(ctx, updateClient,
		arg.ID,
		arg.Name,
		arg.Phone,
		arg.ClientType,
	)
	var i Client
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Phone,
		&i.TotalLoyaltyPoints,
		&i.ValidLoyaltyPoints,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.ClientType,
		&i.Uid,
		&i.IsActive,
		&i.BranchID,
	)
	return i, err
}

const upsertClientLink = `-- name: UpsertClientLink :exec
INSERT INTO client_links (branch_id, register_id, branch_client_id, client_id)
VALUES ($1, $2, $3, $4)
ON CONFLICT (register_id, branch_client_id) DO UPDATE SET client_id = EXCLUDED.client_id
`

type UpsertClientLinkParams struct {
	BranchID       int64 `json:"branch_id"`
	RegisterID     int64 `json:"register_id"`
	BranchClientID int64 `json:"branch_client_id"`
	ClientID       int64 `json:"client_id"`
}

func (q *Queries) UpsertClientLink(ctx context.Context, arg UpsertClientLinkParams) error {
	_, err := q.db.ExecContext(ctx, upsertClientLink,
		arg.BranchID,
		arg.RegisterID,
		arg.BranchClientID,
		arg.ClientID,
	)
	return err
}
